// ============================================
// Module 2: Query Pre-processing & Intent Extraction
// ============================================
const input = $input.first().json;
const query = (input.body?.query || input.query || '').trim();
const queryLower = query.toLowerCase();

// --- Section Detection ---
const sectionMap = [
  { patterns: ['sd', 'software dev', 'software development'], tab: 'CSE_SD_Sec_A', name: 'Software Development A' },
  { patterns: ['sd b', 'software dev b'], tab: 'CSE_SD_Sec_B', name: 'Software Development B' },
  { patterns: ['ai', 'aiml', 'artificial intelligence', 'machine learning', 'ml'], tab: 'CSE_AIML_Sec_A', name: 'AIML A' },
  { patterns: ['ai b', 'aiml b'], tab: 'CSE_AIML_Sec_B', name: 'AIML B' },
  { patterns: ['cys', 'cyber', 'cyber security', 'cybersec'], tab: 'CSE_CyberSec_Sec_A', name: 'Cyber Security A' },
  { patterns: ['cys b', 'cyber b'], tab: 'CSE_CyberSec_Sec_B', name: 'Cyber Security B' },
  { patterns: ['ibm'], tab: 'CSE_IBM_Sec_A', name: 'IBM A' },
  { patterns: ['xebia'], tab: 'CSE_Xebia_Sec_A', name: 'Xebia A' }
];

// --- Day Detection ---
const dayMap = {
  'mon': 'Monday', 'monday': 'Monday',
  'tue': 'Tuesday', 'tuesday': 'Tuesday',
  'wed': 'Wednesday', 'wednesday': 'Wednesday',
  'thu': 'Thursday', 'thursday': 'Thursday',
  'fri': 'Friday', 'friday': 'Friday',
  'sat': 'Saturday', 'saturday': 'Saturday'
};

// --- Time Slot to Row Mapping ---
const timeToRow = {
  '9': 3, '10': 4, '11': 5, '12': 6,
  '13': 7, '1': 7, '14': 8, '2': 8,
  '15': 9, '3': 9, '16': 10, '4': 10
};

// --- Day to Column Mapping ---
const dayToCol = {
  'Monday': 'B', 'Tuesday': 'C', 'Wednesday': 'D',
  'Thursday': 'E', 'Friday': 'F', 'Saturday': 'G'
};

// --- Holiday Detection ---
const holidays = [
  { date: '2026-01-14', event: 'Makar Sankranti' },
  { date: '2026-01-26', event: 'Republic Day' },
  { date: '2026-02-15', event: 'Maha Shivratri' },
  { date: '2026-03-02', event: 'Holi Break' },
  { date: '2026-03-03', event: 'Holika Dahan' },
  { date: '2026-03-04', event: 'Dhulandi' },
  { date: '2026-03-21', event: 'Eid-Ul-Fitr' },
  { date: '2026-03-26', event: 'Ram Navami' },
  { date: '2026-03-31', event: 'Mahavir Jayanti' },
  { date: '2026-04-14', event: 'Dr. Ambedkar Jayanti' },
  { date: '2026-05-28', event: 'Bakr Id/Eid-Ul-Zuha' },
  { date: '2026-08-15', event: 'Independence Day' },
  { date: '2026-08-28', event: 'Raksha Bandhan' },
  { date: '2026-09-04', event: 'Janmashtami' },
  { date: '2026-10-02', event: 'Mahatma Gandhi Jayanti' },
  { date: '2026-10-20', event: 'Dussehra' },
  { date: '2026-10-29', event: 'Karwa Chauth' },
  { date: '2026-11-06', event: 'Dhanteras' },
  { date: '2026-11-07', event: 'Chhoti Deepawali' },
  { date: '2026-11-08', event: 'Deepawali' },
  { date: '2026-11-09', event: 'Vishwakarma Day/Goverdhan Pooja' },
  { date: '2026-11-10', event: 'Deepawali Break' },
  { date: '2026-11-11', event: 'Bhai Dhooj' },
  { date: '2026-11-24', event: 'Guru Nanak Jayanti' },
  { date: '2026-12-25', event: 'Christmas Day' }
];

// Detect section (check longer patterns first)
let detectedSection = null;
let detectedSectionName = null;
for (const sec of sectionMap) {
  for (const p of sec.patterns) {
    if (queryLower.includes(p)) {
      detectedSection = sec.tab;
      detectedSectionName = sec.name;
      break;
    }
  }
  if (detectedSection) break;
}

// Detect day
let detectedDay = null;
const todayWords = ['today', 'aaj'];
const tomorrowWords = ['tomorrow', 'kal'];
const now = new Date();

if (todayWords.some(w => queryLower.includes(w))) {
  const days = ['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'];
  detectedDay = days[now.getDay()];
} else if (tomorrowWords.some(w => queryLower.includes(w))) {
  const days = ['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'];
  const tomorrow = new Date(now);
  tomorrow.setDate(tomorrow.getDate() + 1);
  detectedDay = days[tomorrow.getDay()];
} else {
  for (const [key, day] of Object.entries(dayMap)) {
    if (queryLower.includes(key)) {
      detectedDay = day;
      break;
    }
  }
}

// Detect time
let detectedTime = null;
let detectedRow = null;
const timeMatch = queryLower.match(/(\d{1,2})\s*(?::|\s)?\s*(\d{2})?\s*(am|pm)?/);
if (timeMatch) {
  let hour = parseInt(timeMatch[1]);
  const period = timeMatch[3];
  if (period === 'pm' && hour !== 12) hour += 12;
  if (period === 'am' && hour === 12) hour = 0;
  detectedTime = `${hour}:00`;
  detectedRow = timeToRow[String(hour)] || null;
}

// Build cell range
let cellRange = null;
let fullDayRange = null;
if (detectedSection && detectedDay) {
  const col = dayToCol[detectedDay];
  if (col) {
    if (detectedRow) {
      cellRange = `${detectedSection}!${col}${detectedRow}`;
    }
    fullDayRange = `${detectedSection}!${col}3:${col}10`;
  }
}

// Check holidays
let isHoliday = false;
let holidayEvent = null;
const todayStr = now.toISOString().split('T')[0];
const holiday = holidays.find(h => h.date === todayStr);
if (holiday && todayWords.some(w => queryLower.includes(w))) {
  isHoliday = true;
  holidayEvent = holiday.event;
}

return [{
  json: {
    originalQuery: query,
    detectedSection,
    detectedSectionName,
    detectedDay,
    detectedTime,
    detectedRow,
    cellRange,
    fullDayRange,
    isHoliday,
    holidayEvent,
    needsSection: !detectedSection,
    needsDay: !detectedDay,
    timestamp: new Date().toISOString()
  }
}];

const input = $input.first().json;
return [{
  json: {
    response: `🎉 No classes today — it's ${input.holidayEvent}! Enjoy your day off.`,
    status: 'holiday',
    timestamp: new Date().toISOString()
  }
}];

return [{
  json: {
    response: "I couldn't identify your section. Which section are you in?

Supported sections:
• SD (Software Development)
• AI / AIML
• CYS (Cyber Security)
• IBM
• Xebia

Example: "Monday schedule for SD section"",
    status: 'missing_section',
    timestamp: new Date().toISOString()
  }
}];

// ============================================
// Module 5: Response Formatting & Delivery
// ============================================
const aiResponse = $input.first().json;
const preprocessed = $('Query Preprocessor').first().json;

let response = aiResponse.output || aiResponse.response || aiResponse.text || '';

// Clean formatting
response = response.replace(/```/g, '').trim();

// Add section context header
if (preprocessed.detectedSectionName && preprocessed.detectedDay) {
  const header = `📅 ${preprocessed.detectedDay} — ${preprocessed.detectedSectionName}`;
  if (!response.includes(preprocessed.detectedDay)) {
    response = `${header}\n\n${response}`;
  }
}

if (!response) {
  response = 'Sorry, I could not retrieve the timetable. Please try again with a specific section and day.';
}

return [{
  json: {
    response,
    status: 'success',
    section: preprocessed.detectedSection,
    day: preprocessed.detectedDay,
    timestamp: new Date().toISOString()
  }
}];
